  "gu_serve": "Cosa serve",
  "gu_serve_testo": "Windows 10/11 · Dolphin (gratis, lo installa l'app) · la tua copia del gioco (.iso o .rvz) · circa 2 GB liberi",
  "gu_titolo": "Iniziamo: 3 passi (+1 facoltativo)",
