  "gioca_agg_tit": "Aggiornare Dolphin a {0}?",
  "gioca_agg_testo": "Impostazioni, salvataggi del gioco e texture restano. Gli stati salvati (salvataggi rapidi) fatti con questa versione potrebbero non caricarsi più.",
  "titolo_guida": "Benvenuto!",
  "sub_guida": "Ecco cos'è questo launcher e come iniziare in pochi minuti.",
  "exp_tasti_tit": "Tasti in gioco",
  "exp_tasti": "RB (un colpetto, da solo): cambia costume\nL3 (o freccia giù), in aria: tuffo in picchiata, tenuto un attimo = camera della picchiata\nL3 vicino ai nemici: lock (aggancia il nemico)\nR3 (o Z (RB/R1) + freccia giù): camera principale / alternativa\nSelect (o Z + Start): mappa\nLB (o freccia sinistra + destra): nascondi / mostra l'HUD\nFreccia sinistra / destra: spalla della camera Amazing (e FOV, se hai acceso quel codice)\nZ (RB/R1) + freccia sinistra / destra: nascondi / mostra l'HUD",
  "gu_consiglio": "Se il gioco va a scatti, in Grafica scegli il preset «{0}».",
  "gr_osd": "Messaggi di Dolphin sullo schermo",
  "gr_osd_sub": "Le scritte tipo «9 cheat enabled» o «stato salvato». Spente di base quando avvii dal launcher: le stesse cose le vedi qui. (Se apri il gioco da Dolphin valgono le impostazioni di Dolphin.)",
  "alt_info_tit": "Come si cambia costume in gioco",
  "alt_info": "In gioco dai un colpetto a RB, da solo: passi dal costume principale a quello alternativo, e con un altro colpetto torni indietro. Funziona in qualsiasi momento, anche mentre ti muovi.\n\nRB tenuto o insieme alle frecce fa le sue combinazioni di sempre (camera, HUD, mappa, rallenty) e non cambia costume.\n\nServe il codice «Cambio costume», acceso di base tra gli essenziali in Codici.",
  "alt_info_ok": "Ho capito",
  "lingua": "Lingua",
  "gr_dds_gia": "✓ Le texture sono già in DDS, il formato leggero: occupano circa {0} di RAM. Niente da fare.",
  "gr_t_mac": "Mac (zip esportato)",
