  "gr_pers_bloccato": "Accendi «Personalizzazione avanzata» per cambiare questa impostazione.",
  "gr_sconsigliato": "sconsigliato",
  "gr_globali_conf_tit": "Usare le impostazioni di Dolphin?",
  "gr_globali_conf": "Sconsigliato. La mod è pensata con le impostazioni dell'app (16:9, texture HD precaricate, CPU in overclock per i 60 fps): con quelle generali di Dolphin il gioco può andare peggio o vedersi male. Usalo solo se sai cosa stai facendo.",
