  "imp_gioco": "Quando giochi",
  "gr_backend_mac_sub": "Su Mac usa Metal: è il motore nativo di Apple, il più veloce e stabile. Vulkan e OpenGL solo per prove.",
  "gr_oc_zip_sub": "Serve al codice 60 fps per non rallentare nelle zone piene. Su Mac e Android va bene 300%: scalda meno e non accende le ventole.",
