  "gu_tagline": "Spider-Man 2 for GameCube like you've never seen it. This launcher installs and manages everything for you, without ever opening Dolphin.",
  "gu_g_gioco": "In the game",
  "gu_g_gioco_sub": "they stay even without the app",
  "gu_g_app": "Only with the app",
  "gu_g_app_sub": "while it's open, even minimized",
  "gu_v1": "HD city textures and dozens of suits",
  "gu_v2": "60 fps (and 60 Hz on the European versions), no motion blur, unstretched 16:9 HUD",
  "gu_v7": "New cameras (PS4-style modern, Amazing...): R3 switches to the other one",
  "gu_v8": "Momentum that isn't lost: when landing, with the web zip and when running on walls",
  "gu_a1": "In-game menu (LB + RB): live suits, codes, 3D map and travel, time of day, music",
  "gu_a2": "Webs that change together with the alternate suit",
  "gu_a3": "Camera you can tune while you play",
  "gu_v4": "Quick saves with a photo of where you were",
  "gu_v5": "Also on Android, Xbox, Mac or another PC (Export page)",
  "gu_serve": "What you need",
  "gu_serve_testo": "Windows 10/11 · Dolphin (free, the app installs it) · your copy of the game (.iso or .rvz) · about 2 GB free",
  "gu_titolo": "Let's start: 3 steps (+1 optional)",
  "gu_sub": "Then press Play. No need to open Dolphin: the app does everything.",
  "gu_p1": "Dolphin, the emulator",
  "gu_p1_sub": "It's the program that runs GameCube games on PC. I install it in my own folder (20 MB, from the official site): it doesn't touch the rest of your PC.",
  "gu_p1_ok": "Ready: {0}",
  "gu_p1_installa": "Install Dolphin for me",
