  "gu_p1_mai_aperto": "I found Dolphin but it was never opened (its folder is missing). Use the app's one, or open it once, close it and press Check again.",
  "gu_ricontrolla": "Check again",
  "gu_p2": "The game",
  "gu_p2_sub": "You need your copy of Spider-Man 2 for GameCube as an .iso or .rvz file (not included). I can search your PC, or you pick the file.",
