  "gioca_agg": "Dolphin {0} is out (you have {1}). With a new version, old save states may no longer load.",
  "gioca_agg_b": "Update",
  "gioca_agg_attendi": "Wait for the Dolphin update to finish, then you can play.",
  "gioca_agg_tit": "Update Dolphin to {0}?",
  "gioca_agg_testo": "Settings, game saves and textures stay. Save states made with this version may no longer load.",
  "titolo_guida": "Welcome!",
  "sub_guida": "Here's what this launcher is and how to get started in a few minutes.",
  "exp_tasti_tit": "In-game buttons",
  "exp_tasti": "RB (a quick tap, on its own): switch suit\nL3 (or d-pad down), in the air: dive, held a moment = dive camera\nL3 near enemies: lock-on\nR3 (or Z (RB/R1) + d-pad down): main / alternate camera\nSelect (or Z + Start): map\nLB (or d-pad left + right): hide / show the HUD\nD-pad left / right: Amazing camera shoulder (and FOV, if you turned that code on)\nZ (RB/R1) + d-pad left / right: hide / show the HUD",
  "gu_consiglio": "If the game stutters, pick the “{0}” preset in Graphics.",
  "gr_osd": "Dolphin on-screen messages",
  "gr_osd_sub": "Texts like “9 cheats enabled” or “state saved”. Off by default when you start from the launcher: you see the same things here. (Starting from Dolphin uses Dolphin's settings.)",
  "alt_info_tit": "How to switch suit in game",
  "alt_info": "In game give RB a quick tap on its own: you switch from the main suit to the alternate one, and another tap brings you back. It works anytime, even while moving.\n\nRB held, or with the d-pad, does its usual combos (camera, HUD, map, slow motion) and doesn't switch suit.\n\nIt needs the “Suit switch” code, on by default among the essentials in Codes.",
  "alt_info_ok": "Got it",
  "lingua": "Language",
  "gr_dds_gia": "✓ Textures are already DDS, the light format: they take about {0} of RAM. Nothing to do.",
  "gr_t_mac": "Mac (exported zip)",
  "gr_p_macarm": "Apple Silicon",
  "gr_p_macarm_sub": "Base M1–M4 chips: smooth 1440p.",
  "gr_p_macpro": "Apple Silicon Pro / Max",
  "gr_p_macpro_sub": "Pro, Max or Ultra chips: up to 4K.",
  "gr_p_macintel": "Intel Mac",
  "gr_p_macintel_sub": "Macs up to 2020: smoothness first.",
  "gr_mac_info": "These settings don't touch this PC: they go into the Mac zip (Export page). Pick the preset for the Mac's processor and change what you like.",
  "gr_mac_res": "MacBook screen: 4×. Full HD monitor: 3×. 4K monitor: 6× (Pro/Max chips only).",
  "gr_mac_salvato": "Mac settings saved: the next Mac zip uses them.",
  "gr_tex_mac_sub": "DDS is fine on Macs (Apple Silicon and Intel read the BC7 format): lighter. PNG only if you have problems.",
  "gr_cache_mac_sub": "No stutter when changing area. In DDS the textures use about 0.6 GB of RAM.",
  "exp_grafica_mac": "Graphics for Mac",
  "gr_pers": "Advanced customization",
  "gr_pers_sub": "You can always change the image settings. Turn this on to change the technical ones too (smoothness, textures).",
  "gr_pers_bloccato": "Turn on “Advanced customization” to change this setting.",
  "gr_sconsigliato": "not recommended",
  "gr_globali_conf_tit": "Use Dolphin's settings?",
  "gr_globali_conf": "Not recommended. The mod is built around the app's settings (16:9, preloaded HD textures, CPU overclocked for 60 fps): with Dolphin's general ones the game may run or look worse. Use it only if you know what you're doing.",
  "gr_globali_si": "Use Dolphin anyway",
  "imp_gioco": "When you play",
  "gr_backend_mac_sub": "On Mac use Metal: it's Apple's native engine, the fastest and most stable. Vulkan and OpenGL only for testing.",
  "gr_oc_zip_sub": "Needed by the 60 fps code to avoid slowdowns in busy areas. On Mac and Android 300% is fine: less heat, no fans.",
  "comandi": "Controls",
  "comandi_tit": "In-game controls",
  "com_legenda": "Z = RB on Xbox pads, R1 on the Retroid · L3 / R3 = click the left / right stick · change buttons on the Controller page",
  "com_skin": "Switch suit: main ↔ alternate",
  "com_skin_sub": "A quick tap of RB on its own. Choose the alternate suit in Suits.",
  "com_tuffo": "Dive (in the air)",
  "com_tuffo_sub": "Hold it for a moment and the dive camera stays on by itself until you web; a quick tap just dives.",
  "com_lock": "Lock on to enemies (game)",
  "com_lock_sub": "Near enemies L3 locks on to the closest one.",
  "com_lock_tuffo": " In the air too: the lock wins over the dive.",
  "com_lock_r3": " R3 never locks on, and while locked it doesn't switch camera either.",
  "com_cam": "Camera: yours ↔ the original",
  "com_cam_sub": "You tune your camera live in Spider-Cam.",
  "com_cam_mod": "Camera: main ↔ alternate",
  "com_cam_mod_sub": "You can pick modern, Amazing, cinematic, first person (experimental), improved, yours or original: choose the two cameras in Spider-Cam or in the in-game menu (LB + RB).",
  "com_fov_su": "Widen the view (FOV +1°)",
  "com_fov_giu": "Narrow the view (FOV −1°)",
  "com_spalla_sx": "Amazing camera over the left shoulder",
  "com_spalla_dx": "Amazing camera over the right shoulder",
  "com_spalla_sub": "only with the Amazing camera; it starts on the right",
  "com_hud_off": "Hide the HUD, for clean shots and videos",
  "com_hud_on": "Show the HUD again",
  "com_nota": "They work with the essential codes on (Codes page): they are by default.",
  "com_rag_nota": "The alternate suit webs switch with the suit only while the app is open.",
  "com_o": "or",
  "ins_fatto_altro": "Later, whenever you like, you can change suits, codes and graphics from the other pages.",
  "applico_tx": "Applying textures…",
  "applico_skin": "Applying the suit…",
  "applico_hud": "Applying HUD and buttons…",
