  "tr_rilascia_tit": "Drop here",
  "tr_rilascia": "Install zips, suits, webs, HUDs, buttons or texture packs: I'll figure out what they are and where they go.",
  "tr_controllo": "Checking the files…",
  "tr_ok": "Ready to install: {0}.",
  "tr_diversi": "{0}: right name, but not the file I know (maybe a newer version).",
  "tr_non_so": "{0}: I don't know what to do with it. Drop zip, rar or 7z archives, or folders.",
  "tr_occupato": "Wait for the current job to finish, then try again.",
  "ins_trascina": "You can also drag the zips onto the window: I'll recognise them.",
  "gr_fps30_pc_sub": "Turns off the 60 fps code in every version (same switch as in the Codes page): the game goes back to its original 30 fps, handy if your PC can't keep up.",
  "cam_avvia_tit": "Tune the camera live",
  "cam_avvia_sub": "I'll open the game in a window with the camera code off for this session only: move the sliders and see the result right away. When you like it, “Save to game”. From the next session the code is back on by itself.",
  "cam_avvia_btn": "Start {0} in a window",
  "cam_avviato": "Camera code off for this session only: the sliders are in charge now. It turns back on by itself next time.",
  "cam_avviato_senza": "The camera code wasn't on: the sliders work live.",
  "cam_avvia_nessuno": "I can't find the game disc: add it from the launcher (Play › Choose file or Search PC), then come back here.",
  "cam_avvia_vai": "Go to the launcher",
  "av_conflitto2": "The camera code is on in this session: it overwrites the slider values, so your changes don't show. Restart without the code to tune live.",
  "cam_riavvia_btn": "Restart without code",
  "cam_riavvio_tit": "Restarting the game",
  "cam_riavvio": "I'm closing the game (if Dolphin asks to confirm, answer Yes) and reopening it in a window without the camera code.",
  "cam_non_chiuso": "The game didn't close: close it yourself and press “Start in a window”.",
