  "cam_finestra": "Windowed",
  "cam_chiudi_conf": "If Dolphin asks to confirm, answer Yes.",
  "imp_sopra_sub": "When you play in a window, the game stays above other windows: you still see it while changing suits, codes or camera in the app. Also in Spider-Cam.",
  "imp_tasti_auto": "On-screen buttons for your controller",
  "imp_tasti_auto_sub": "When you start the game, with a PlayStation pad I put PlayStation buttons in the game (and Xbox ones with an Xbox pad). It uses the buttons you last picked in HUD & buttons.",
  "tasti_auto_ok": "On-screen buttons changed",
  "tasti_auto_sub": "I put \"{0}\" for the controller you connected.",
  "tr_ok_spunta": "Recognised and ticked: {0}. Press “Install” at the bottom of the page.",
  "tr_gia_tit": "Already in the library",
  "tr_gia": "{0}: already in the library, no need to install it again. To redo it from scratch, tick it and press “Install”.",
  "ins_rim": "Remove",
  "ins_rim_tip": "Removes the pack from the library",
