  "alt_info_tit": "So wechselst du im Spiel den Anzug",
  "alt_info": "Drück im Spiel kurz RB, allein: Du wechselst vom Haupt- zum alternativen Anzug, und ein weiterer kurzer Druck bringt dich zurück. Das geht jederzeit, auch in Bewegung.\n\nGehaltenes RB oder RB mit dem Steuerkreuz macht seine üblichen Kombinationen (Kamera, HUD, Karte, Zeitlupe) und wechselt den Anzug nicht.\n\nDafür braucht es den Code „Anzugwechsel“, standardmäßig bei den wichtigen Codes an.",
