  "gr_globali_conf_tit": "Dolphins Einstellungen nutzen?",
  "gr_globali_conf": "Nicht empfohlen. Die Mod ist auf die App-Einstellungen ausgelegt (16:9, vorgeladene HD-Texturen, übertaktete CPU für 60 fps): mit Dolphins allgemeinen kann das Spiel schlechter laufen oder aussehen. Nur nutzen, wenn du weißt, was du tust.",
