  "gioca_agg_testo": "Réglages, sauvegardes du jeu et textures restent. Les états faits avec cette version risquent de ne plus se charger.",
  "titolo_guida": "Bienvenue !",
  "sub_guida": "Voici ce qu'est ce lanceur et comment démarrer en quelques minutes.",
  "exp_tasti_tit": "Touches en jeu",
  "exp_tasti": "RB (pression rapide, seul) : changer de costume\nL3 (ou croix bas), en l'air : plongeon, maintenu un instant = caméra de plongeon\nL3 près des ennemis : verrouillage\nR3 (ou Z (RB/R1) + croix bas) : caméra principale / alternative\nSelect (ou Z + Start) : carte\nLB (ou croix gauche + droite) : masquer / afficher le HUD\nCroix gauche / droite : épaule de la caméra Amazing (et FOV, si tu as activé ce code)\nZ (RB/R1) + croix gauche / droite : masquer / afficher le HUD",
  "gu_consiglio": "Si le jeu saccade, choisis le préréglage « {0} » dans Graphismes.",
  "gr_osd": "Messages de Dolphin à l'écran",
  "gr_osd_sub": "Les textes comme « 9 codes activés » ou « état sauvegardé ». Désactivés par défaut au lancement depuis le lanceur : tu vois la même chose ici. (Depuis Dolphin, ce sont ses réglages qui comptent.)",
  "alt_info_tit": "Comment changer de costume en jeu",
  "alt_info": "En jeu, donne une pression rapide sur RB, seul : tu passes du costume principal à l'alternatif, et une autre pression te ramène. Ça marche à tout moment, même en mouvement.\n\nRB maintenu ou avec la croix fait ses combinaisons habituelles (caméra, HUD, carte, ralenti) et ne change pas de costume.\n\nIl faut le code « Changement de costume », activé par défaut parmi les essentiels dans Codes.",
  "alt_info_ok": "Compris",
  "lingua": "Langue",
  "gr_dds_gia": "✓ Les textures sont déjà en DDS, le format léger : elles occupent environ {0} de RAM. Rien à faire.",
  "gr_t_mac": "Mac (zip exporté)",
