  "gr_p_macintel": "Mac Intel",
  "gr_p_macintel_sub": "Mac jusqu'à 2020 : la fluidité d'abord.",
  "gr_mac_info": "Ces réglages ne touchent pas ce PC : ils vont dans le zip pour Mac (page Exporter). Choisis le préréglage du processeur du Mac et change ce que tu veux.",
  "gr_mac_res": "Écran de MacBook : 4×. Écran Full HD : 3×. Écran 4K : 6× (puces Pro/Max seulement).",
  "gr_mac_salvato": "Réglages Mac enregistrés : le prochain zip pour Mac les utilise.",
  "gr_tex_mac_sub": "Le DDS convient aux Mac (Apple Silicon et Intel lisent le BC7) : plus léger. PNG seulement en cas de souci.",
  "gr_cache_mac_sub": "Pas de saccades en changeant de zone. En DDS les textures utilisent environ 0,6 Go de RAM.",
