  "gr_pers_bloccato": "Active « Personnalisation avancée » pour changer ce réglage.",
  "gr_sconsigliato": "déconseillé",
  "gr_globali_conf_tit": "Utiliser les réglages de Dolphin ?",
  "gr_globali_conf": "Déconseillé. Le mod est pensé avec les réglages de l'appli (16:9, textures HD préchargées, CPU surcadencé pour les 60 fps) : avec ceux de Dolphin le jeu peut tourner ou s'afficher moins bien. À utiliser seulement si tu sais ce que tu fais.",
  "gr_globali_si": "Utiliser Dolphin quand même",
  "imp_gioco": "Quand tu joues",
  "gr_backend_mac_sub": "Sur Mac utilise Metal : le moteur natif d'Apple, le plus rapide et stable. Vulkan et OpenGL seulement pour tester.",
  "gr_oc_zip_sub": "Nécessaire au code 60 fps pour éviter les ralentissements. Sur Mac et Android 300 % suffit : moins de chauffe, pas de ventilos.",
  "comandi": "Commandes",
