  "exp_tasti_tit": "Botones en el juego",
  "exp_tasti": "RB (un toque, solo): cambiar de traje\nL3 (o cruceta abajo), en el aire: picado, mantenido un momento = cámara de picado\nL3 cerca de enemigos: fijación\nR3 (o Z (RB/R1) + cruceta abajo): cámara principal / alternativa\nSelect (o Z + Start): mapa\nLB (o cruceta izquierda + derecha): ocultar / mostrar el HUD\nCruceta izquierda / derecha: hombro de la cámara Amazing (y FOV, si activaste ese código)\nZ (RB/R1) + cruceta izquierda / derecha: ocultar / mostrar el HUD",
  "gu_consiglio": "Si el juego va a tirones, elige el ajuste «{0}» en Gráficos.",
  "gr_osd": "Mensajes de Dolphin en pantalla",
  "gr_osd_sub": "Textos como «9 trucos activados» o «estado guardado». Apagados por defecto al iniciar desde el lanzador: lo mismo lo ves aquí. (Si abres el juego desde Dolphin valen sus ajustes.)",
  "alt_info_tit": "Cómo cambiar de traje en el juego",
  "alt_info": "En el juego da un toque rápido a RB, solo: pasas del traje principal al alternativo, y con otro toque vuelves. Funciona en cualquier momento, incluso en movimiento.\n\nRB mantenido o con la cruceta hace sus combinaciones de siempre (cámara, HUD, mapa, cámara lenta) y no cambia de traje.\n\nHace falta el código «Cambio de traje», activado por defecto entre los esenciales en Códigos.",
